import{_ as a,c as l,g as e,o as n}from"./chunks/framework.CCxIPCIe.js";const m=JSON.parse('{"title":"四三八","description":"","frontmatter":{"title":"四三八","date":"2026-10-01T13:20:08.929Z","length":"538字","time":"2分钟","aside":false,"hash":1062304391},"headers":[],"relativePath":"idea/438.md","filePath":"idea/438.md"}'),s={name:"idea/438.md"};function r(o,t,p,i,d,c){return n(),l("div",null,t[0]||(t[0]=[e("p",null,"这次在 interspeech 开会的时候遇到了 DiaMoeTTS 的一作，一个清华的研三老弟。这篇文章去年 10 月份我就关注到了，因为语宝和方言苑的平台都推送过，那时我还以为二者有什么合作关系。",-1),e("p",null,"结果一问老弟，他说完全没听说过。我说我还是很想问问有没有谁认识中国语言大学的人。语宝平台花着纳税人的钱，动员各地高校贡献田野调查，完成美其名曰的方言保护的政绩工程，结果数据闭源。方言数据都已经珍稀得不能再珍稀了，你还搁这闭源，你保护个毛线呢？你是觉得这些东西陈列在博物馆里，供在水晶棺材里观赏它的死亡形态有某种诡异的美感是吧？语言，分明是可以超越个体的死亡而复活的。",-1),e("p",null,"扯远了。有趣的是这老弟也是个 p 社战犯，也爱好看黑格尔。不过他对黑格尔的阅读比我深得多（说真的我还只停留在一些外围的介绍书上），这次来参会还随身带了一本德语原版哲学百科全书（这里感慨一下清华的库藏）。那天晚上一块吃了顿饭，我请他介绍了一下现象学，他问了我一点关于拉康精神分析的东西。",-1),e("p",null,"交流下来我才发现拉康和黑格尔、胡塞尔是如此针锋相对的东西，按老弟的说法后两者都是笛卡尔我思精神的发挥。而拉康恰恰是反对我思的明证性的，或者说它反对我思中心主义/主体中心主义。",-1),e("p",null,"不过后来也没有太多时间再深入讨论。闲聊中得知老弟是呼伦贝尔人，也不想卷了，想回老家挖煤的镇子上找个国企的班儿上，这点倒是和我想法一致。",-1),e("p",null,"开会总是有许多意外之喜，这个老弟是我这次遇到最有意思的人了。",-1)]))}const _=a(s,[["render",r]]);export{m as __pageData,_ as default};
